// © 2026 SIKUMI LAB — SITE BASE
import {VERSION,PROFILES,clone,read as readLocal,readAll,save,seed,stateOf,hasNew,publishedNews,orderedNews,newsDateOrder,displayDate,dateInput,preparePublication,badgeIds,badgeLabels,badgeLength,customBadgeText,WORK_KEY,publicPart,workChanged,readWork,saveWork,prepareWork} from './model.js?v=20261009-2';
import {CONDITIONS, CONDITIONS_REVISION} from './conditions.js?v=20261009-2';
import {newsList,newsDetailShell,bindNewsDetails,closeNewsDetail} from './news-details.js?v=20261009-2';
import {itemCards,itemDetailShell,bindItemDetails,closeItemDetail} from './item-details.js?v=20261009-2';
import {PAGE_IMAGE_SLOTS,BADGE_OPTIONS,CUSTOM_BADGE_LIMIT} from './site-config.js?v=20261009-2';
import {attachReorder} from './reorder.js?v=20261009-2';
import {CONNECTED,readShared,loadShared,publishShared,submitSharedInquiry,updateSharedInquiry,retrySharedInquiry,sharedHistory,retrySharedPublication} from './connection.js?v=20261009-2';
const read=profile=>CONNECTED?(readShared()||seed(profile)):readLocal(profile);
const profile=new URLSearchParams(location.search).get('profile');
const selected=Object.hasOwn(PROFILES,profile)?profile:'shop';
const page=document.body.dataset.page;
let sampleHeaderHidden=sessionStorage.getItem('site-base-demo-bar-hidden')==='yes';
let published=read(selected),work=page==='admin'?readWork(selected):null;
let content=clone(work?.draft||published),tab='items',editorDraft=null,entered=CONNECTED||sessionStorage.getItem('site-base-demo-entered')==='yes';
const app=document.querySelector('#app'),dialog=document.querySelector('#dialog');
let dialogGuard=null,exitPrompt=null,afterWorkCommit=null,authorizedExit=false,saving=false;
const formBaselines=new WeakMap();
function formValue(form){return JSON.stringify([...new FormData(form)].map(([k,v])=>[k,typeof v==='string'?v:v.name]));}
function pendingForms(){return [...app.querySelectorAll('#basic-form,#days-form,.inquiry-form')].filter(f=>formBaselines.has(f)&&formBaselines.get(f)!==formValue(f));}
function hasPending(){return Boolean(dialog.open&&dialogGuard?.dirty()||pendingForms().length||work&&workChanged(work.base,content));}
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const lines=v=>esc(String(v??'').replaceAll('\\n','\n'));
const link=(file,hash='')=>`./${file}?profile=${selected}${CONNECTED&&page==='admin'&&file==='index.html'?'&preview=1':''}${hash}`;
const now=()=>Number(localStorage.getItem('site-base-demo-clock'))||Date.now();
const imgSrc=v=>String(v||'').match(/^(\/media\/[a-f0-9]{64}|\.\/assets\/[a-z-]+\.svg|data:image\/(jpeg|png|webp);base64,[A-Za-z0-9+/=]+)$/)?v:'./assets/atelier.svg';
function toast(message){document.querySelector('#toast').textContent=message;clearTimeout(toast.timer);toast.timer=setTimeout(()=>document.querySelector('#toast').textContent='',6000);}
function persist(next,message='このブラウザに保存しました。',immediate=false) {
 if(page==='admin'&&!immediate){const base=work?.base||clone(published);content=clone(next);content.lastUpdated=base.lastUpdated;work={base,draft:clone(content)};try{saveWork(selected,workChanged(base,content)?work:null);render();toast('作業内容に追加しました。最後に「変更内容を確認」からまとめて反映してください。');return true;}catch{render();toast('作業内容を保存できませんでした。画面内に残しています。容量や保存設定をご確認ください。');return false;}}
 try{save(next);published=clone(next);content=next;render();toast(message);return true;}catch{toast('保存できませんでした。ブラウザの空き容量や保存設定を確認してください。入力内容は画面に残しています。');return false;}
}
function workingNotice(){const dirty=work&&workChanged(work.base,content);return `<section class="working-bar" aria-label="編集内容の確定"><div><strong>${dirty?'未反映の変更があります':'公開側と同じ内容です'}</strong><p class="small muted">編集や写真の変更は作業内容として保存します。最後の確定まで公開側は変わりません。</p></div><div class="actions"><button class="primary" id="work-review" ${dirty?'':'disabled'}>変更内容を確認</button><button id="work-discard" ${dirty?'':'disabled'}>未反映の変更を取り消す</button></div></section>`;}
function reviewValue(field,value){if(value==null||value==='')return 'なし';if(['startAt','endAt','articleAt'].includes(field))return displayDate(value,true);if(field==='hidden')return value?'非表示':'表示';if(field==='published')return value?'公開する':'下書き';if(typeof value==='boolean')return value?'オン':'オフ';if(field==='newMode')return value==='manual'?'手動で外す':'設定日数で自動終了';return String(value);}
function reviewGroup(title,kind,status,rows,photos='',id=''){
 const added=status.includes(' · 追加');
 return `<section class="review-group" data-review-kind="${esc(kind)}" data-review-id="${esc(id)}"><header><h3>${esc(title)}</h3><p class="small muted">${esc(status)}</p></header><dl class="compact-fields">${rows.filter(([label])=>!added||label!=='名称').map(([label,before,after])=>`<div><dt>${esc(label)}</dt><dd>${added?'':`<span class="review-before">${lines(before)}</span><span class="review-arrow" aria-label="から"> → </span>`}<strong>${lines(after)}</strong></dd></div>`).join('')}</dl>${photos}</section>`;
}
function groupedReview(base,snapshot,prepared){
 const groups=[];
 const picture=(src,label)=>`<figure><figcaption>${esc(label)}</figcaption>${src?`<img class="page-photo-preview" src="${imgSrc(src)}" alt="${esc(label)}">`:'<p class="small muted">写真なし</p>'}</figure>`;
 for(const key of ['items','news']){
  const label=key==='items'?'掲載内容':'お知らせ',beforeList=key==='news'?orderedNews(base):base[key],afterList=key==='news'?orderedNews(snapshot):snapshot[key];
  const beforeIds=beforeList.filter(i=>afterList.some(next=>next.id===i.id)).map(i=>i.id),afterIds=afterList.filter(i=>beforeList.some(old=>old.id===i.id)).map(i=>i.id);
  const reordered=JSON.stringify(beforeIds)!==JSON.stringify(afterIds);
  for(const [index,item]of afterList.entries()){
   const oldIndex=beforeList.findIndex(i=>i.id===item.id),old=beforeList[oldIndex];
   if(old&&JSON.stringify(old)===JSON.stringify(item)&&(!reordered||oldIndex===index))continue;
   const rows=[];
   if(!old||reordered&&oldIndex!==index)rows.push(['表示順',old?`${oldIndex+1}番目`:'なし',`${index+1}番目`]);
   for(const [field,title]of [['name','名称'],['price','価格'],['body','本文'],['hidden','表示状態'],['published','公開設定'],['startAt','公開日時'],['endAt','終了日時'],['newEnabled','NEW'],['newMode','NEWの消し方'],['featured','ピックアップ'],['kind','種類'],['articleAt','記事日付']])if(old?old[field]!==item[field]:item[field]!=null&&item[field]!==''&&(field==='newMode'?item.newEnabled:field==='published'?!item.published:typeof item[field]==='boolean'?item[field]:true))rows.push([title,reviewValue(field,old?.[field]),reviewValue(field,item[field])]);
   if(old?old.image!==item.image:Boolean(item.image))rows.push(['写真',old?.image?'写真あり':'写真なし',item.image?'写真あり':'写真なし（画像枠を省く）']);
   if(old?JSON.stringify([old.badges,old.customBadge,old.customBadgeEnabled])!==JSON.stringify([item.badges,item.customBadge,item.customBadgeEnabled]):badgeLabels(item).length>0)rows.push(['バッジ',old?badgeLabels(old).join('・')||'なし':'なし',badgeLabels(item).join('・')||'なし']);
   if(item.reapplyNew&&item.newEnabled)rows.push(['NEWの起点','現在の起点を使用','今回の確定で付け直す']);
   const photos=old?.image!==item.image&&(old?.image||item.image)?`<div class="photo-review">${picture(old?.image,'変更前の写真')}${picture(item.image,'変更後の写真')}</div>`:'';
   groups.push(reviewGroup(item.name,key,`${label} · ${old?'変更':'追加'} / ${stateOf(prepared[key].find(i=>i.id===item.id),now())}`,rows,photos,item.id));
  }
  for(const old of beforeList)if(!afterList.some(item=>item.id===old.id))groups.push(reviewGroup(old.name,key,`${label} · 削除`,[['掲載','保存済みの内容','削除する']],'',old.id));
 }
 if((base.newsOrderMode??'date')!==(snapshot.newsOrderMode??'date')&&!groups.some(group=>group.includes('data-review-kind="news"')))groups.push(reviewGroup('お知らせの表示順','news','変更した項目',[['並び方','投稿日で自動的に並べ替え','一覧の並び順を維持']]));
 const shopRows=[],shopLabels={name:'公開名',intro:'トップの見出し',description:'紹介文',itemsLabel:'掲載内容の見出し',address:'所在地',hours:'営業時間・受付時間',closed:'休業日'};
 for(const [key,label]of Object.entries(shopLabels))if(snapshot.shop[key]!==base.shop[key])shopRows.push([label,reviewValue(key,base.shop[key]),reviewValue(key,snapshot.shop[key])]);
 if(shopRows.length)groups.push(reviewGroup('基本情報','basic','変更した項目',shopRows));
 for(const slot of PAGE_IMAGE_SLOTS){const old=base.photos[slot.id],next=snapshot.photos[slot.id];if(JSON.stringify(old)===JSON.stringify(next))continue;
  const rows=[];if(old.alt!==next.alt)rows.push(['写真の説明',reviewValue('alt',old.alt),reviewValue('alt',next.alt)]);
  if(old.src!==next.src)rows.push(['写真',old.src?'写真あり':'写真なし',next.src?'写真あり':'写真なし（画像枠を省く）']);
  const photos=old.src!==next.src?`<div class="photo-review">${picture(old.src,'変更前の写真')}${picture(next.src,'変更後の写真')}</div>`:'';
  groups.push(reviewGroup(slot.label,'photos','ページの写真 · 変更',rows,photos,slot.id));
 }
 if(base.days!==snapshot.days)groups.push(reviewGroup('表示設定','settings','変更した項目',[['NEWの共通日数',`${base.days}日`,`${snapshot.days}日`]]));
 return `<p class="review-summary">変更対象 ${groups.length}件。アイテムごとに変更前後を確認してください。</p><div class="review-groups">${groups.join('')}</div>`;
}
function confirmWork(after=null){
 if(typeof after!=='function')after=null;
 if(!work||!workChanged(work.base,content)){after?.();return;}
 const snapshot=clone(content),base=clone(work.base);let prepared;
 try{prepared=prepareWork(base,snapshot,read(selected),now());}catch(err){toast(err.message);return;}
 review('変更をまとめて確認',[],async()=>{try{if(CONNECTED){const final=await publishShared(selected,snapshot,base.serverRevision);published=clone(final);content=clone(final);toast(final.publishNotification==='failed'?'変更を共有保存しました。更新通知に失敗しました。履歴で確認してください。':'変更をまとめて共有保存しました。');}else{const final=prepareWork(base,snapshot,read(selected),now());if(!persist(final,'変更をまとめて反映しました。',true))return false;}work=null;try{saveWork(selected,null);}catch{toast('反映しましたが作業内容の片付けに失敗しました。');}render();const done=afterWorkCommit;afterWorkCommit=null;if(done)setTimeout(done,0);return true;}catch(err){toast(err.message);return false;}},()=>{afterWorkCommit=null;closeDialog();},groupedReview(base,snapshot,prepared));
 afterWorkCommit=after;dialog.classList.add('compact-review');dialogGuard={dirty:()=>Boolean(work&&workChanged(work.base,content)),apply:()=>{},discard:()=>{const done=afterWorkCommit;afterWorkCommit=null;closeDialog();done?.();},title:after?'画面を移動しますか？':'確認を閉じますか？',discardLabel:after?'作業を残して移動':'作業を残して閉じる',message:'まだ確定していません。作業を残して閉じる・移動する場合は、公開側を変更せず、作業一覧の内容を残します。'};
 dialog.querySelector('#review-confirm').textContent='確定・まとめて反映';
}


try {if(!CONNECTED){const saved=readAll()[selected];if(!saved||saved.sampleNewsRevision!==published.sampleNewsRevision||PAGE_IMAGE_SLOTS.some(slot=>!saved.photos?.[slot.id])||[...saved.items,...saved.news].some(item=>!Array.isArray(item.badges)||typeof item.customBadge!=='string'||typeof item.customBadgeEnabled!=='boolean'))save(published);}}catch{toast('このブラウザでは保存できません。保存設定をご確認ください。');}
function pageImage(id,extra=''){
const photo=content.photos[id];if(!photo?.src)return '';
return `<img data-page-image="${esc(id)}" src="${imgSrc(photo.src)}" alt="${esc(photo.alt)}" ${extra}>`;
}
function demoBar(){if(page==='site'&&sampleHeaderHidden)return '';return `<div class="demo-bar"><div class="demo-brand"><strong>SITE BASE</strong><span class="demo-byline">by SIKUMI LAB</span></div><label class="small">業種 <select id="profile" aria-label="業種の見本">${Object.entries(PROFILES).map(([k,v])=>`<option value="${k}" ${k===selected?'selected':''}>${v}</option>`).join('')}</select></label><div class="links"><a href="${link('index.html')}">公開サイト</a><a href="${link('admin.html')}">設定画面</a><a href="${link('terms.html')}">提供条件</a>${page==='site'?'<button type="button" class="demo-hide" id="demo-hide" aria-label="SITE BASEのサンプルヘッダを隠す" title="サンプルヘッダを隠す">×</button>':''}</div></div>`;}
function footer(){return `<footer class="site-footer"><div class="wrap footer-row"><span>SITE BASE by SIKUMI LAB</span><span>表示サンプル v${VERSION}</span></div><div class="wrap small">${CONNECTED?"内部接続テスト：確定内容は共有保存し、問い合わせをメール通知します。架空の内容でお試しください。":"変更はこのブラウザ内のみ。メール認証・メール送信・他の端末への共有は行いません。"}</div><div class="wrap footer-copyright">© 2026 SIKUMI LAB</div></footer>`;}
function newBadge(item){return hasNew(item,now(),content.days)?'<span class="badge new">NEW</span>':'';}
function badges(item){return `${newBadge(item)}${badgeLabels(item).map(label=>`<span class="badge">${esc(label)}</span>`).join(' ')}`;}
function renderSite(){const s=content.shop;const items=content.items.filter(i=>stateOf(i,now())==='公開中');const news=publishedNews(content,now());return `<header class="site-header">${demoBar()}<div class="wrap header-main"><a class="brand" href="${link('index.html')}">${esc(s.name)}</a><button class="burger" id="burger" aria-label="メニューを開く" aria-expanded="false" aria-controls="site-nav"><span></span><span></span><span></span></button><nav class="site-nav" id="site-nav" aria-label="ページ内の案内"><a href="#about">私たちについて</a><a href="#items">${esc(s.itemsLabel)}</a><a href="#news">お知らせ</a><a href="#access">ご案内</a><a href="#contact">お問い合わせ</a></nav></div></header><main id="main" class="site-main"><section id="about" class="wrap hero ${content.photos.hero?.src?"":"no-photo"}"><div><p class="eyebrow">${esc(s.kind)} / KOMOREBI</p><h1 class="pre">${lines(s.intro)}</h1><p class="pre">${lines(s.description)}</p><a class="button primary" href="#items">${esc(s.itemsLabel)}を見る <span aria-hidden="true">↗</span></a></div>${pageImage('hero')}</section><section id="items" class="section pale"><div class="wrap"><div class="section-head"><div><p class="eyebrow">${esc(s.category)}</p><h2>${esc(s.itemsLabel)}</h2></div><p class="muted small">内容・価格はすべて架空の見本です。</p></div><div class="cards">${itemCards(items,{esc,imgSrc,badges})}</div></div></section><section id="news" class="section"><div class="wrap"><div class="section-head"><div><p class="eyebrow">LATEST NEWS</p><h2>お知らせ</h2></div><p class="muted small">季節のご案内と、日々のこと。</p></div><div class="news-list">${newsList(news,esc,badges)}</div></div></section><section id="access" class="section pale"><div class="wrap two-col"><div><p class="eyebrow">INFORMATION</p><h2>ご案内</h2><p>気軽に立ち寄れる場所で、<br>お待ちしています。</p><p class="small muted">このお店・教室・サービスは架空です。</p>${pageImage('access','class="access-photo" loading="lazy"')}</div><dl class="facts"><dt>名称</dt><dd>${esc(s.name)}</dd><dt>所在地</dt><dd>${esc(s.address)}</dd><dt>営業時間</dt><dd>${esc(s.hours)}</dd><dt>お休み</dt><dd>${esc(s.closed)}</dd><dt>最終更新日</dt><dd><time id="last-updated">${displayDate(content.lastUpdated)}</time></dd></dl></div></section><section id="contact" class="section"><div class="wrap two-col"><div><p class="eyebrow">CONTACT</p><h2>お問い合わせ</h2><p>ご相談の入口を、ひとつに。</p><p class="muted">送信後の受付履歴と対応状況を、設定画面で確認できる見本です。</p><div class="notice">このフォームは操作サンプルです。<strong>架空の内容でお試しください。</strong>${CONNECTED?"受付を共有保存し、設定済みの通知先へ実際にメールを送信します。":"メールは送信されず、このブラウザ内だけに保存します。"}</div></div><form id="contact-form" class="contact-form"><label class="field"><span>お名前</span><input name="name" required maxlength="80" placeholder="デモ 太郎" autocomplete="off"></label><label class="field"><span>メールアドレス</span><input name="email" type="email" required maxlength="150" placeholder="demo@example.com" autocomplete="off"></label><label class="field"><span>ご相談内容</span><textarea name="body" required maxlength="2000" placeholder="架空の内容を入力してください"></textarea></label><button class="primary" type="submit">${CONNECTED?"テスト問い合わせを送信":"受付を試す（メール送信なし）"}</button></form></div></section></main>${newsDetailShell}${itemDetailShell}${sampleHeaderHidden?'<button type="button" class="demo-show small" id="demo-show">SITE BASEを表示</button>':''}${footer()}`;}
function adminHeader(){return `<header class="admin-header">${demoBar()}<div class="wrap header-main"><a class="admin-brand" href="${link('admin.html')}"><span class="admin-logo"><span class="admin-logo-title">SITE BASE</span><span class="admin-logo-byline">by SIKUMI LAB</span></span><span class="small muted admin-label">設定画面</span></a><a class="button quiet small" href="${link('index.html')}">表示を確認 ↗</a></div></header>`;}
function adminEntry(){return `${adminHeader()}<main id="main" class="entry"><p class="eyebrow">YOUR SITE, YOUR PACE.</p><h1>日々の更新を、<br>自分のペースで。</h1><p>写真や価格、お知らせを変更して、公開サイトの見え方を試せます。</p><div class="notice">本番では、登録したメールアドレスに届く認証コードで入る予定です。この見本は認証せずに開けます。</div><button class="primary" id="enter">設定画面の見本を開く</button></main>${footer()}`;}
const tabs={items:'掲載内容',news:'お知らせ',photos:'ページの写真',basic:'基本情報',inquiries:'問い合わせ',settings:'表示設定'};
function renderAdmin(){if(!entered)return adminEntry();return `${adminHeader()}<div class="admin-shell"><nav class="sidebar" aria-label="設定項目">${Object.entries(tabs).map(([key,name])=>`<button data-tab="${key}" class="${tab===key?'active':''}" ${tab===key?'aria-current="page"':''}>${name}</button>`).join('')}</nav><main class="admin-main" id="main"><p class="eyebrow">${esc(content.shop.name)}</p>${workingNotice()}${renderPanel()}</main></div>${footer()}`;}
function row(i,kind,index,length,entries=[]){const up=index>0&&(kind==='items'||Boolean(entries[index-1].featured)===Boolean(i.featured)),down=index<length-1&&(kind==='items'||Boolean(entries[index+1].featured)===Boolean(i.featured));return `<article class="list-row ${i.image?"":"no-photo"} item-row reorderable ${kind==='news'?'news-row':''}" data-index="${index}" data-entry-id="${esc(i.id)}" role="listitem">${i.image?`<img src="${imgSrc(i.image)}" alt="" draggable="false">`:""}<div class="item-copy"><h3>${esc(i.name)}</h3><p>${i.price?esc(i.price)+'　':''}<span class="state ${stateOf(i,now())==='公開中'?'live':''}">${stateOf(i,now())}</span> ${kind==='news'&&i.featured?'<span class="badge">ピックアップ</span>':''} ${badges(i)}</p><p class="small muted">${kind==='news'?'投稿日 '+displayDate(i.articleAt)+' / ':''}${i.startAt?'開始 '+displayDate(i.startAt,true):'即時公開'}${i.endAt?' / 終了 '+displayDate(i.endAt,true):' / 終了なし'}</p></div><div class="actions row-controls"><button data-edit="${i.id}" data-kind="${kind}">編集</button><button data-hide="${i.id}" data-kind="${kind}">${i.hidden?'再表示':'非表示'}</button><button data-move="${i.id}" data-kind="${kind}" data-direction="-1" aria-label="${esc(i.name)}を上へ" ${up?'':'disabled'}>↑</button><button data-move="${i.id}" data-kind="${kind}" data-direction="1" aria-label="${esc(i.name)}を下へ" ${down?'':'disabled'}>↓</button><button class="danger" data-delete="${i.id}" data-kind="${kind}">削除</button></div></article>`;}
function field(name,label,value='',type='text',extra=''){return `<label class="field"><span>${label}</span><input name="${name}" type="${type}" value="${esc(value)}" ${extra}></label>`;}
function textArea(name,label,value,extra=''){return `<label class="field"><span>${label}</span><textarea name="${name}" ${extra}>${lines(value)}</textarea></label>`;}
function editedTime(value,before){return value?(before&&value===dateInput(before)?before:new Date(value).getTime()):null;}
function renderPanel(){if(tab==='items'||tab==='news'){const a=tab==='news'?orderedNews(content):content.items;return `<div class="admin-heading"><div><h1>${tab==='items'?esc(content.shop.itemsLabel):'お知らせ'}</h1><p class="muted">${tab==='items'?'名称・価格・写真・表示順を変更できます。':`保存 ${a.length}/20件（非表示も含む）・公開表示は最大10件`}</p></div><div class="actions">${tab==='news'?`<button id="news-date-order" ${a.length<2?'disabled':''}>日付順に戻す</button>`:''}<button class="primary" data-add="${tab}" ${tab==='news'&&a.length>=20?'disabled':''}>＋ 新しく追加</button></div></div><div class="notice">${work&&workChanged(work.base,content)?'編集中の内容はまだ公開側に反映されていません。最後に上のボタンからまとめて確定します。':'未反映の変更はありません。編集後は、上のボタンからまとめて確定できます。'}<p class="clock-note">表示確認時刻：${displayDate(now(),true)}${localStorage.getItem('site-base-demo-clock')?'（手動設定）':'（現在時刻）'}</p></div>${a.length?'<p class="reorder-hint">カードを長押しして移動 ／ 右端の↑↓でも移動</p>':''}${tab==='news'?'<p class="small muted">ピックアップは先頭に固定します。それぞれの区分の中で並べ替えできます。「日付順に戻す」は投稿日が新しい順に並べ直します。反映には最後の確定が必要です。</p>':''}<div data-reorder-list="${tab}" role="list" aria-label="${tab==='items'?'掲載内容':'お知らせ'}の表示順">${a.map((i,index)=>row(i,tab,index,a.length,a)).join('')||'<p>まだ登録されていません。</p>'}</div>`;}
if(tab==='photos')return `<h1>ページの写真</h1><p class="muted">トップやご案内など、ページ内の写真をそれぞれ差し替えられます。</p><div class="notice">写真の配置と表示枠は初期設定で用意します。縦横比を保ち、表示枠の中央を基準にトリミングします。掲載内容・お知らせの写真は、それぞれの編集画面で変更できます。</div><div class="page-photo-grid">${PAGE_IMAGE_SLOTS.map(slot=>`<article class="page-photo-card"><h3>${esc(slot.label)}</h3>${pageImage(slot.id,'class="page-photo-preview"')}<button data-photo-edit="${esc(slot.id)}">${content.photos[slot.id]?.src?"写真を差し替える":"写真を追加する"}</button></article>`).join('')}</div>`;
if(tab==='basic')return `<h1>基本情報</h1><p class="muted">見出しや紹介文を、事業に合わせる画面の見本です。</p><form id="basic-form" class="admin-panels">${field('name','公開名',content.shop.name,'text','required maxlength="80"')}${textArea('intro','トップの見出し',content.shop.intro,'required maxlength="180"')}${textArea('description','紹介文',content.shop.description,'maxlength="1000"')}${field('itemsLabel','掲載内容の見出し',content.shop.itemsLabel,'text','required maxlength="40"')}${field('address','所在地',content.shop.address,'text','maxlength="180"')}${field('hours','営業時間・受付時間',content.shop.hours,'text','maxlength="180"')}${field('closed','休業日',content.shop.closed,'text','maxlength="180"')}<button class="primary">変更を作業内容へ追加</button></form>`;
if(tab==='inquiries')return `<h1>問い合わせ</h1><div class="notice">返信は普段のメールで行い、この画面では受付履歴と対応状況を管理します。${CONNECTED?"受付は共有保存されています。通知に失敗しても受付内容は残り、この画面で通知を再試行できます。":"この見本の受付情報はブラウザ内のみで、メール通知は行いません。"}個人情報は入力しないでください。</div>${content.inquiries.map(i=>`<article class="inquiry"><h3>${esc(i.name)}</h3><p class="muted small">${displayDate(i.receivedAt,true)} / ${esc(i.email)}</p><p class="pre">${lines(i.body)}</p><form class="inquiry-form" data-id="${i.id}"><div class="field-grid"><label class="field"><span>対応状況（手動更新）</span><select name="status">${['未対応','対応中','対応済み'].map(v=>`<option ${i.status===v?'selected':''}>${v}</option>`).join('')}</select></label>${textArea('memo','内部メモ',i.memo,'maxlength="1500"')}</div><p class="small muted">${esc(i.notification)}</p><button>対応状況・メモを保存</button>${CONNECTED&&["pending","failed"].includes(i.notificationState)?`<button type="button" data-notification-retry="${esc(i.id)}">通知を再試行</button>`:""}</form></article>`).join('')||'<p>受付履歴はありません。</p>'}`;
return `<h1>表示設定</h1><div class="admin-panels"><section class="panel"><h3>NEWを自動で消すまでの日数</h3><p class="small muted">サイト全体で1つの設定です。手動方式のNEWには影響しません。14日は見本の仮設定です。</p><form id="days-form">${field('days','表示日数',content.days,'number','required min="1" max="365" step="1"')}<button class="primary">変更を作業内容へ追加</button></form></section><section class="panel"><h3>予約・自動終了を試す</h3><p class="small muted">確認時刻を変えると、公開サイトと設定画面の表示が切り替わります。保存した公開日時は変わりません。日時の入力は端末の時刻、一覧の表示は日本時間です。</p><form id="clock-form">${field('clock','表示確認時刻',dateInput(now()),'datetime-local','required')}<div class="actions"><button>この時刻で表示を確認</button><button type="button" id="clock-reset">現在時刻へ戻す</button></div></form></section><section class="panel"><h3>この見本について</h3><p>${CONNECTED?"メール認証・共有保存・問い合わせ通知を接続した内部テストです。公開サンプルとは保存先が異なります。":"メール認証・共有保存・メール通知は本番で接続する予定です。この見本にログイン情報はありません。"}</p><a href="${link('terms.html')}">提供条件を見る</a></section>${CONNECTED?'<section class="panel"><h3>公開の更新履歴</h3><button id="shared-history">履歴を取得</button><div id="shared-history-list" aria-live="polite"></div></section>':""}<section class="panel"><h3>試した内容をリセット</h3><p class="small muted">選択中の業種の公開用の編集内容を、初期状態として作業内容へ追加します。受付履歴は変更しません。</p><button id="reset" class="danger">この業種の見本をリセット</button></section></div>`;
}
function renderTerms() {
  return `${adminHeader()}
    <main id="main" class="wrap terms">
      <p class="eyebrow">SITE BASE by SIKUMI LAB</p>
      <h1>提供の考え方と利用条件</h1>
      <p>身近な人の事業を、自分で更新できるサイトで支える。そのための、友人に限定した取り組みです。</p>
      <p class="small muted">${esc(CONDITIONS_REVISION)}</p>
      <div class="notice">この条件は、シクミラボからサイトの提供を受ける方へ向けたものです。一般向けの無料サービスとして募集するものではありません。</div>
      ${CONDITIONS.map(({title,paragraphs},index)=>`
        <article>
          <p class="term-number">${String(index+1).padStart(2,'0')}</p>
          <h2>${esc(title)}</h2>
          ${paragraphs.map(paragraph=>`<p>${esc(paragraph)}</p>`).join('')}
        </article>`).join('')}
      <p class="small muted">このページは提供条件の表示見本です。了承の記録を送信・保存する機能はありません。</p>
      <a class="button primary" href="${link('index.html')}">公開サイトの見本へ</a>
    </main>${footer()}`;
}
let headerObserver,stopReorder;
function fitAdminByline(){
const byline=document.querySelector('.admin-logo-byline');if(!byline)return;
// Match the two line widths by distributing spare space across all characters.
// Keep a single text node so the brand is read as a phrase by assistive tools.
byline.style.letterSpacing='0px';
const range=document.createRange();range.selectNodeContents(byline);
const spare=byline.getBoundingClientRect().width-range.getBoundingClientRect().width;
byline.style.letterSpacing=`${spare/Array.from(byline.textContent).length}px`;
}
function render(){stopReorder?.();stopReorder=null;closeNewsDetail();closeItemDetail();app.innerHTML=page==='site'?renderSite():page==='admin'?renderAdmin():renderTerms();fitAdminByline();bind();app.querySelectorAll('#basic-form,#days-form,.inquiry-form').forEach(f=>formBaselines.set(f,formValue(f)));headerObserver?.disconnect();const header=document.querySelector('header');headerObserver=new ResizeObserver(()=>document.documentElement.style.setProperty('--header-height',`${header.getBoundingClientRect().height}px`));headerObserver.observe(header);}
function moveEntry(kind,from,to){
const entries=kind==='news'?orderedNews(content):content.items;
if(!Number.isInteger(from)||!Number.isInteger(to)||from===to||from<0||to<0||from>=entries.length||to>=entries.length)return;
if(kind==='news'){
 const group=entries.map((entry,index)=>Boolean(entry.featured)===Boolean(entries[from].featured)?index:-1).filter(index=>index>=0);
 to=Math.max(group[0],Math.min(group.at(-1),to));
 if(from===to){toast('ピックアップと通常のお知らせは、それぞれの区分の中で並べ替えてください。');return;}
}
const c=clone(content);if(kind==='news'){c.news=orderedNews(c);c.newsOrderMode='manual';}
c[kind].splice(to,0,c[kind].splice(from,1)[0]);const position=window.scrollY;persist(c);window.scrollTo({top:position,behavior:'instant'});
}
function resetNewsDateOrder(){
const sorted=newsDateOrder(content.news);
if(JSON.stringify(sorted.map(n=>n.id))===JSON.stringify(orderedNews(content).map(n=>n.id))){toast('すでに投稿日が新しい順です。');return;}
const c=clone(content);c.news=sorted;c.newsOrderMode='manual';persist(c);
}
function closeDialog(){dialogGuard=null;dialog.close();document.body.style.overflow='';editorDraft=null;dialog.classList.remove('compact-review');}
function askExit({apply,discard,title='編集を終了しますか？',applyLabel='変更内容を確認',discardLabel='入力を破棄して閉じる',message='「変更内容を確認」で作業一覧へ追加し、最後の確認へ進みます。「入力を破棄して閉じる」は、この画面の入力だけを取り消します。作業一覧へ追加済みの内容は残ります。'}){
 if(exitPrompt)return;
 const previous=document.activeElement,previousOverflow=document.body.style.overflow;document.body.style.overflow='hidden';exitPrompt=document.createElement('dialog');exitPrompt.className='exit-confirm';exitPrompt.setAttribute('aria-labelledby','exit-title');
 exitPrompt.innerHTML=`<div class="dialog-top"><h2 id="exit-title">${esc(title)}</h2><button id="exit-keep" aria-label="編集を続ける">閉じる</button></div><p>${esc(message)}</p><div class="actions"><button class="primary" id="exit-apply">${esc(applyLabel)}</button><button id="exit-discard">${esc(discardLabel)}</button><button id="exit-back">編集を続ける</button></div>`;
 document.body.append(exitPrompt);exitPrompt.showModal();
 const dismiss=()=>{exitPrompt.close();exitPrompt.remove();exitPrompt=null;document.body.style.overflow=previousOverflow;if(previous?.isConnected)previous.focus({preventScroll:true});};
 exitPrompt.querySelector('#exit-apply').onclick=async()=>{dismiss();await apply();};exitPrompt.querySelector('#exit-discard').onclick=()=>{dismiss();discard();};
 for(const id of ['exit-keep','exit-back'])exitPrompt.querySelector('#'+id).onclick=dismiss;
 exitPrompt.addEventListener('cancel',e=>{e.preventDefault();dismiss();});exitPrompt.addEventListener('click',e=>{if(e.target===exitPrompt)dismiss();});
}
function requestDialogClose(){if(saving){toast('保存処理中です。完了するまでお待ちください。');return;}if(dialogGuard?.dirty())askExit(dialogGuard);else closeDialog();}
function frameDialog(){
 dialog.classList.add('framed-dialog');
 const form=dialog.querySelector('form'),host=form||dialog,actions=host.querySelector('.sticky-actions'),body=document.createElement('div');body.className='dialog-scroll';body.tabIndex=0;body.setAttribute('aria-label','編集・確認内容');
 for(const node of [...host.childNodes])if(node!==actions&&!node.classList?.contains('dialog-top'))body.append(node);
 host.insertBefore(body,actions);if(actions)actions.classList.add('dialog-footer');
 if(form?.elements.price){const name=form.elements.name.closest('.field'),price=form.elements.price.closest('.field'),group=document.createElement('div');group.className='field-grid editor-primary-fields';name.before(group);group.append(name,price);}
 dialog.scrollTop=0;body.scrollTop=0;
}
function fitDialog(){const v=window.visualViewport;dialog.style.setProperty('--modal-viewport-height',`${v?.height??innerHeight}px`);dialog.style.setProperty('--modal-viewport-top',`${v?.offsetTop??0}px`);}
window.visualViewport?.addEventListener('resize',fitDialog);window.visualViewport?.addEventListener('scroll',fitDialog);window.addEventListener('resize',fitDialog);
function openDialog(html){dialogGuard=null;dialog.classList.remove('compact-review');dialog.innerHTML=html;frameDialog();fitDialog();document.body.style.overflow='hidden';if(!dialog.open)dialog.showModal();dialog.querySelectorAll('[data-close]').forEach(b=>b.onclick=requestDialogClose);}
dialog.addEventListener('cancel',e=>{e.preventDefault();requestDialogClose();});
dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)requestDialogClose();}});
window.addEventListener('beforeunload',e=>{if(page==='admin'&&!authorizedExit&&hasPending()){e.preventDefault();e.returnValue='';}});
async function applyPendingForms(){for(const form of pendingForms()){if(!form.reportValidity())return false;if(CONNECTED&&form.matches('.inquiry-form'))await form.onsubmit({preventDefault(){}});else form.requestSubmit();if(form.isConnected&&pendingForms().includes(form))return false;}return true;}
function requestNavigation(next,includeWork=true){if(saving){toast('保存処理中です。完了するまでお待ちください。');return;}const leave=()=>{if(includeWork){authorizedExit=true;setTimeout(()=>{authorizedExit=false;},1000);}next();};if(pendingForms().length||includeWork&&work&&workChanged(work.base,content))askExit({apply:async()=>{if(await applyPendingForms()){if(includeWork)confirmWork(leave);else leave();}},discard:leave,title:'画面を移動しますか？',applyLabel:includeWork?'変更内容を確認':'入力を保存して移動',discardLabel:pendingForms().length?'入力を破棄して移動':'作業を残して移動',message:includeWork?'「変更内容を確認」で最後の確認へ進みます。確認せず移動すると、この画面の未保存の入力は取り消します。作業一覧へ追加済みの内容は残ります。':'この画面に未保存の入力があります。保存して移動するか、この画面の入力だけを取り消して移動できます。作業一覧へ追加済みの内容は残ります。'});else leave();}
function review(title,rows,commit,back=null,body=null,{confirmLabel='OK・反映する',notice=CONNECTED?'確定すると、写真を含めて共有保存します。':'確定すると、このブラウザの見本に反映します。インターネット全体への公開ではありません。'}={}){openDialog(`<div class="dialog-top"><h2 id="dialog-title">${esc(title)}</h2><button type="button" data-close aria-label="確認を閉じる">閉じる</button></div><p class="small muted">${esc(notice)}</p>${body??`<dl class="review-grid">${rows.map(([k,v])=>`<dt>${esc(k)}</dt><dd>${lines(v)}</dd>`).join('')}</dl>`}<div class="actions sticky-actions">${back?'<button id="review-back">編集へ戻る</button>':'<button data-close>キャンセル</button>'}<button class="primary" id="review-confirm">${esc(confirmLabel)}</button></div>`);dialog.querySelector('#review-confirm').onclick=async()=>{const button=dialog.querySelector('#review-confirm');if(button.disabled)return;const controls=[...dialog.querySelectorAll('button')].map(b=>[b,b.disabled]);saving=true;dialog.setAttribute('aria-busy','true');for(const[b]of controls)b.disabled=true;try{if(await commit()!==false)closeDialog();}catch(error){toast(error.message);}finally{saving=false;dialog.removeAttribute('aria-busy');for(const[b,disabled]of controls)if(b.isConnected)b.disabled=disabled;}};if(back)dialog.querySelector('#review-back').onclick=back;}
function openPagePhotoEditor(id,draft=null){
const slot=PAGE_IMAGE_SLOTS.find(s=>s.id===id);if(!slot)return;
const before=clone(content.photos[id]),next=clone(draft||before);
openDialog(`<div class="dialog-top"><h2 id="dialog-title">${esc(slot.label)}の差し替え</h2><button data-close aria-label="写真の編集を閉じる">閉じる</button></div><form id="page-photo-form"><label class="field"><span>写真を選ぶ</span><input id="page-photo-file" type="file" accept="image/jpeg,image/png,image/webp"><span class="small muted">最大8MB。保存時に容量を整え、表示枠の中央を基準にトリミングします。</span></label><img id="page-photo-preview" class="page-photo-preview" ${next.src?`src="${imgSrc(next.src)}"`:"hidden"} alt="差し替える写真の見本"><button type="button" id="page-photo-remove" ${next.src?"":"hidden"}>写真を外す</button>${field('alt','写真の説明（読み上げ用）',next.alt,'text','maxlength="180"')}<p id="page-photo-error" class="error" role="status" aria-live="polite"></p><div class="actions sticky-actions"><button type="button" data-close>キャンセル</button><button class="primary" type="submit" aria-label="写真の変更を作業内容へ追加">作業一覧へ追加</button></div></form>`);
const form=dialog.querySelector('#page-photo-form'),error=form.querySelector('#page-photo-error');let busy=false;
form.querySelector('#page-photo-remove').onclick=()=>{next.src='';const preview=form.querySelector('#page-photo-preview');preview.hidden=true;preview.removeAttribute('src');form.querySelector('#page-photo-file').value='';form.querySelector('#page-photo-remove').hidden=true;};
form.querySelector('#page-photo-file').onchange=async e=>{
const file=e.target.files[0];if(!file)return;busy=true;error.textContent='写真を処理しています…';form.querySelector('[type=submit]').disabled=true;
try{const src=await optimizePhoto(file);if(!form.isConnected)return;next.src=src;form.querySelector('#page-photo-preview').src=src;form.querySelector('#page-photo-preview').hidden=false;form.querySelector('#page-photo-remove').hidden=false;error.textContent='';}
catch(err){error.textContent=err.message;}
finally{busy=false;form.querySelector('[type=submit]').disabled=false;e.target.value='';}
};
form.onsubmit=e=>{
e.preventDefault();if(busy||!form.reportValidity())return;next.alt=String(new FormData(form).get('alt')).trim();
const c=clone(content);c.photos[id]=clone(next);c.lastUpdated=Date.now();
if(persist(c)){closeDialog();return true;}return false;
};
const initial=formValue(form),initialSrc=next.src;dialogGuard={dirty:()=>busy||initial!==formValue(form)||initialSrc!==next.src,apply:()=>{if(busy)return toast('写真の処理が終わってから確認してください。');if(form.onsubmit({preventDefault(){}}))confirmWork();},discard:closeDialog};
}
function openEditor(kind,id,draft=null){const before=content[kind].find(i=>i.id===id);const item=draft||clone(before||{id:crypto.randomUUID(),name:'',price:'',body:'',image:'',kind:'お知らせ',articleAt:now(),published:false,hidden:false,startAt:null,endAt:null,newEnabled:false,newMode:'auto',featured:false,badges:[],customBadge:'',customBadgeEnabled:false});editorDraft=item;
openDialog(`<div class="dialog-top"><h2 id="dialog-title">${before?'掲載内容を編集':'新しく追加'}</h2><button data-close aria-label="編集を閉じる">閉じる</button></div><form id="editor-form">${field('name','名称・タイトル',item.name,'text','required maxlength="100"')}${kind==='items'?field('price','価格（空欄なら表示しない）',item.price,'text','maxlength="100" placeholder="2,800円 / 月額 / 要相談"'):''}${textArea('body','紹介文・本文',item.body,'maxlength="2000"')}${kind==='news'?`<div class="field-grid"><label class="field"><span>種類</span><select name="kind"><option ${item.kind==='お知らせ'?'selected':''}>お知らせ</option><option ${item.kind==='キャンペーン'?'selected':''}>キャンペーン</option></select></label>${field('articleAt','記事の日付',dateInput(item.articleAt).slice(0,10),'date','required')}</div><label class="check"><input name="featured" type="checkbox" ${item.featured?'checked':''}>ピックアップ（先頭に固定・複数設定可）</label>`:''}<label class="field"><span>写真（任意）</span><input id="photo-file" type="file" accept="image/jpeg,image/png,image/webp"><img class="preview-photo" id="photo-preview" ${item.image?`src="${imgSrc(item.image)}"`:"hidden"} alt="選択中の写真"><span class="small muted">JPEG・PNG・WebP / 最大8MB。容量を整えて保存し、中央を基準にトリミング表示します。</span></label><button type="button" id="photo-remove" ${item.image?"":"hidden"}>写真を外す</button><p class="small muted">写真なしでも掲載できます。写真がなければ画像の枠も表示しません。</p><fieldset class="editor-options badge-options"><legend>表示するバッジ（複数選択）</legend><div class="badge-choices">${BADGE_OPTIONS.map(option=>`<label class="check"><input type="checkbox" name="badges" value="${option.id}" ${badgeIds(item).includes(option.id)?'checked':''}>${esc(option.label)}</label>`).join('')}<label class="check"><input type="checkbox" name="customBadgeEnabled" id="custom-badge-enabled" ${item.customBadgeEnabled?'checked':''}>自由入力を付ける</label><label class="check"><input id="new-enabled" name="newEnabled" type="checkbox" ${item.newEnabled?'checked':''}>NEWを付ける</label></div>${field('customBadge',`自由入力（全角${CUSTOM_BADGE_LIMIT}文字まで・1つ）`,item.customBadge,'text','maxlength="60" placeholder="例：予約限定" aria-describedby="custom-badge-count"')}<p id="custom-badge-count" class="small muted" aria-live="polite"></p><p class="small muted">選択したバッジを表示します。「終了」も表示用の言葉で、掲載期間は下で設定します。NEW以外はチェックを外すまで残ります。</p><h3>NEWの表示期間</h3><label class="field" id="new-mode-field" ${item.newEnabled?'':'hidden'}><span>消し方</span><select name="newMode"><option value="auto" ${item.newMode==='auto'?'selected':''}>${content.days}日後に自動で消す</option><option value="manual" ${item.newMode==='manual'?'selected':''}>手動で外すまで残す</option></select></label>${before?.firstPublishedAt?'<label class="check" id="reapply-field"><input name="reapply" type="checkbox">今回の公開でNEWを付け直す（期間を再開）</label>':''}<p class="small muted">付けない場合は表示しません。通常の編集では表示期間を延ばしません。</p></fieldset><div class="editor-options"><h3>掲載する期間</h3><div class="field-grid">${field('startAt','公開日時（空欄なら今すぐ）',item.startAt?dateInput(item.startAt):'','datetime-local')}${field('endAt','終了日時（空欄なら終了なし）',item.endAt?dateInput(item.endAt):'','datetime-local')}</div><p class="small muted">日時は端末の時刻で入力してください。現在の表示確認時刻：${displayDate(now(),true)}</p><label class="check"><input name="hidden" type="checkbox" ${item.hidden?'checked':''}>非表示にする</label></div><p class="error" id="editor-error" role="alert"></p><div class="actions sticky-actions"><button type="button" data-close>キャンセル</button><button type="button" id="save-draft" aria-label="下書きとして作業一覧へ追加">下書きを一覧へ</button><button class="primary" type="submit" aria-label="編集内容を作業一覧へ追加">作業一覧へ追加</button></div></form>`);
const form=dialog.querySelector('#editor-form');if(form.elements.reapply)form.elements.reapply.checked=Boolean(item.reapplyNew);form.querySelector('#new-enabled').onchange=e=>{form.querySelector('#new-mode-field').hidden=!e.target.checked;};
const customInput=form.elements.customBadge,customEnabled=form.elements.customBadgeEnabled;
function validateCustom(){let error='';try{const text=customBadgeText(customInput.value);if(customEnabled.checked&&!text)error='自由入力バッジの文字を入力してください。';}catch(err){error=err.message;}customInput.setCustomValidity(error);form.querySelector('#custom-badge-count').textContent=`${badgeLength(customInput.value.trim().normalize('NFC'))} / ${CUSTOM_BADGE_LIMIT}文字`;}
customInput.addEventListener('input',validateCustom);customInput.addEventListener('compositionend',validateCustom);customEnabled.addEventListener('change',validateCustom);validateCustom();
form.querySelector('#photo-remove').onclick=()=>{item.image='';const preview=form.querySelector('#photo-preview');preview.hidden=true;preview.removeAttribute('src');form.querySelector('#photo-file').value='';form.querySelector('#photo-remove').hidden=true;};
let photoBusy=false;form.querySelector('#photo-file').onchange=async e=>{if(!e.target.files[0])return;photoBusy=true;form.querySelector('#editor-error').textContent='写真を処理しています…';try{const value=await optimizePhoto(e.target.files[0]);if(!form.isConnected)return;item.image=value;form.querySelector('#photo-preview').src=value;form.querySelector('#photo-preview').hidden=false;form.querySelector('#photo-remove').hidden=false;form.querySelector('#editor-error').textContent='';}catch(err){form.querySelector('#editor-error').textContent=err.message;}finally{photoBusy=false;}};
function submit(publish){validateCustom();if(!form.reportValidity())return;if(photoBusy){form.querySelector('#editor-error').textContent='写真の処理が終わってから確認してください。';return;}
const f=new FormData(form);const next={...item,name:String(f.get('name')).trim(),body:String(f.get('body')).trim(),price:kind==='items'?String(f.get('price')).trim():'',badges:badgeIds({badges:f.getAll('badges')}),customBadge:badgeLength(String(f.get('customBadge')).trim().normalize('NFC'))<=CUSTOM_BADGE_LIMIT?customBadgeText(f.get('customBadge')):'',customBadgeEnabled:f.has('customBadgeEnabled'),newEnabled:f.has('newEnabled'),newMode:f.get('newMode'),hidden:f.has('hidden'),startAt:editedTime(f.get('startAt'),item.startAt),endAt:editedTime(f.get('endAt'),item.endAt)};
if(!next.name){form.querySelector('#editor-error').textContent='名称を入力してください。';return;}
if(kind==='news'){next.kind=f.get('kind');next.featured=f.has('featured');const date=String(f.get('articleAt'));next.articleAt=date===dateInput(item.articleAt).slice(0,10)?item.articleAt:new Date(date+'T12:00:00').getTime();}
const final={...next,published:publish,reapplyNew:f.has('reapply')&&next.newEnabled};
if(final.endAt&&final.endAt<=(final.startAt||now())){form.querySelector('#editor-error').textContent='終了日時は公開日時より後にしてください。';return;}
if(!before&&kind==='news'&&content.news.length>=20){toast('お知らせは非表示を含め20件までです。');return;}
const c=clone(content);if(kind==='news'){c.news=orderedNews(content);c.newsOrderMode='manual';}const index=c[kind].findIndex(i=>i.id===final.id);if(index>=0)c[kind][index]=final;else if(kind==='news')c.news.unshift(final);else c[kind].push(final);if(persist(c)){closeDialog();return true;}return false;
}
const initial=formValue(form),initialImage=item.image;dialogGuard={dirty:()=>photoBusy||initial!==formValue(form)||initialImage!==item.image,apply:()=>{if(submit(true))confirmWork();},discard:closeDialog};
form.onsubmit=e=>{e.preventDefault();submit(true);};form.querySelector('#save-draft').onclick=()=>submit(false);
}
async function optimizePhoto(file){if(!['image/jpeg','image/png','image/webp'].includes(file.type))throw new Error('JPEG・PNG・WebPの写真を選んでください。');if(file.size>8*1024*1024)throw new Error('写真は8MB以下で選んでください。');const bitmap=await createImageBitmap(file);try{const scale=Math.min(1,1600/Math.max(bitmap.width,bitmap.height));const canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(bitmap.width*scale));canvas.height=Math.max(1,Math.round(bitmap.height*scale));canvas.getContext('2d').drawImage(bitmap,0,0,canvas.width,canvas.height);return canvas.toDataURL('image/webp',.8);}finally{bitmap.close();}}
function bind(){if(document.querySelector('#profile'))document.querySelector('#profile').onchange=e=>{location.href=`./${page==='site'?'index':page}.html?profile=${e.target.value}`;};
if(page==='site'){document.querySelector('#demo-hide')?.addEventListener('click',()=>{sampleHeaderHidden=true;sessionStorage.setItem('site-base-demo-bar-hidden','yes');render();});document.querySelector('#demo-show')?.addEventListener('click',()=>{sampleHeaderHidden=false;sessionStorage.removeItem('site-base-demo-bar-hidden');render();});bindNewsDetails(publishedNews(content,now()),{esc,lines,imgSrc,badges,displayDate});bindItemDetails(content.items.filter(i=>stateOf(i,now())==='公開中'),{esc,lines,imgSrc,badges,onOpen:closeNewsDetail});const burger=document.querySelector('#burger');burger.onclick=()=>{const expanded=burger.getAttribute('aria-expanded')!=='true';burger.setAttribute('aria-expanded',String(expanded));burger.setAttribute('aria-label',expanded?'メニューを閉じる':'メニューを開く');document.querySelector('#site-nav').classList.toggle('open',expanded);};document.querySelectorAll('#site-nav a').forEach(a=>a.onclick=()=>{burger.setAttribute('aria-expanded','false');document.querySelector('#site-nav').classList.remove('open');});let contactAttempt;document.querySelector('#contact-form').onsubmit=async e=>{e.preventDefault();const form=e.target,f=new FormData(form);if(CONNECTED){const button=form.querySelector('[type=submit]');if(button.disabled)return;button.disabled=true;const data=Object.fromEntries(f),signature=JSON.stringify(data);if(contactAttempt?.signature!==signature)contactAttempt={signature,id:crypto.randomUUID()};try{const result=await submitSharedInquiry(selected,{id:contactAttempt.id,...data});contactAttempt=null;form.reset();toast(result.notification==='sent'?'問い合わせを保存し、通知を送信しました。':'問い合わせを保存しました。通知状況は設定画面で確認できます。');}catch(error){toast(error.message);}finally{button.disabled=false;}return;}const c=clone(content);c.inquiries.unshift({id:crypto.randomUUID(),name:String(f.get('name')).trim(),email:String(f.get('email')).trim(),body:String(f.get('body')).trim(),receivedAt:Date.now(),status:'未対応',memo:'',notification:'未送信（表示サンプルはメールを送信しません）'});persist(c,'架空の受付内容を、このブラウザに保存しました。設定画面で確認できます。');};return;}
if(page!=='admin')return;
if(!entered){document.querySelector('#enter').onclick=()=>{entered=true;sessionStorage.setItem('site-base-demo-entered','yes');render();};return;}
document.querySelector('#work-review')?.addEventListener('click',confirmWork);document.querySelector('#work-discard')?.addEventListener('click',()=>review('未反映の変更を取り消す',[['対象','作業中の変更だけを取り消し、公開側の内容へ戻します。']],()=>{try{saveWork(selected,null);work=null;published=read(selected);content=clone(published);render();return true;}catch{toast('取り消せませんでした。作業内容は残しています。');return false;}},null,null,{confirmLabel:'変更を取り消す',notice:'未反映の作業内容を取り消します。公開側の内容は変わりません。'}));
document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{const left=document.querySelector('.sidebar').scrollLeft;requestNavigation(()=>{tab=b.dataset.tab;render();document.querySelector('.sidebar').scrollLeft=left;document.querySelector(`[data-tab="${tab}"]`).focus({preventScroll:true});window.scrollTo({top:0,behavior:'instant'});},false);});document.querySelector('[data-add]')?.addEventListener('click',e=>openEditor(e.currentTarget.dataset.add));document.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>openEditor(b.dataset.kind,b.dataset.edit));
document.querySelectorAll('[data-photo-edit]').forEach(b=>b.onclick=()=>openPagePhotoEditor(b.dataset.photoEdit));
document.querySelectorAll('[data-hide]').forEach(b=>b.onclick=()=>{const c=clone(content),i=c[b.dataset.kind].find(i=>i.id===b.dataset.hide);i.hidden=!i.hidden;c.lastUpdated=Date.now();persist(c);});
document.querySelectorAll('[data-delete]').forEach(b=>b.onclick=()=>{const c=clone(content),i=c[b.dataset.kind].find(i=>i.id===b.dataset.delete);c[b.dataset.kind]=c[b.dataset.kind].filter(a=>a.id!==i.id);persist(c);});
document.querySelectorAll('[data-move]').forEach(b=>b.onclick=()=>{const kind=b.dataset.kind,entries=kind==='news'?orderedNews(content):content.items,index=entries.findIndex(i=>i.id===b.dataset.move);moveEntry(kind,index,index+Number(b.dataset.direction));});document.querySelector('#news-date-order')?.addEventListener('click',resetNewsDateOrder);
const reorderList=document.querySelector('[data-reorder-list]');if(reorderList)stopReorder=attachReorder(reorderList,(from,to)=>moveEntry(reorderList.dataset.reorderList,from,to));
document.querySelector('#basic-form')?.addEventListener('submit',e=>{e.preventDefault();const c=clone(content),f=new FormData(e.target);for(const[k,v]of f)c.shop[k]=String(v).trim();c.lastUpdated=Date.now();persist(c);});
document.querySelectorAll('.inquiry-form').forEach(f=>f.onsubmit=async e=>{e.preventDefault();if(CONNECTED){const button=f.querySelector('button');if(button.disabled)return;button.disabled=true;try{const latest=await updateSharedInquiry(selected,f.dataset.id,Object.fromEntries(new FormData(f)));published=latest;content.inquiries=clone(latest.inquiries);if(work)work.draft.inquiries=clone(latest.inquiries);render();toast('対応状況と内部メモを共有保存しました。');}catch(error){toast(error.message);}finally{button.disabled=false;}return;}const c=clone(content),i=c.inquiries.find(i=>i.id===f.dataset.id),v=new FormData(f);i.status=v.get('status');i.memo=v.get('memo');const current=read(selected);current.inquiries=c.inquiries;if(persist(current,'対応状況と内部メモを保存しました。',true)&&work){content={...clone(work.draft),inquiries:current.inquiries};work.draft.inquiries=current.inquiries;render();}});
document.querySelectorAll('[data-notification-retry]').forEach(b=>b.onclick=async()=>{b.disabled=true;try{const result=await retrySharedInquiry(selected,b.dataset.notificationRetry);published=await loadShared(selected,true);content.inquiries=clone(published.inquiries);if(work)work.draft.inquiries=clone(published.inquiries);render();toast(result.state==='sent'?'通知を送信しました。':'通知結果：'+result.state);}catch(error){toast(error.message);}finally{b.disabled=false;}});
document.querySelector('#shared-history')?.addEventListener('click',async e=>{const button=e.currentTarget;button.disabled=true;try{const history=await sharedHistory(selected);const list=document.querySelector('#shared-history-list');if(!list)return;list.innerHTML=history.map(row=>`<p>公開版 ${esc(row.revision)} ／ ${displayDate(row.createdAt,true)} ／ ${esc(row.notification)} ${['pending','failed'].includes(row.notification)?`<button data-history-retry="${esc(row.id)}">更新通知を再試行</button>`:''}</p>`).join('')||'<p>まだ更新履歴はありません。</p>';list.querySelectorAll('[data-history-retry]').forEach(b=>b.onclick=async()=>{b.disabled=true;try{const result=await retrySharedPublication(selected,b.dataset.historyRetry);toast(result.state==='sent'?'更新通知を送信しました。':'更新通知結果：'+result.state);button.click();}catch(error){toast(error.message);}finally{if(b.isConnected)b.disabled=false;}});}catch(error){toast(error.message);}finally{button.disabled=false;}});
document.querySelector('#days-form')?.addEventListener('submit',e=>{e.preventDefault();const value=Number(new FormData(e.target).get('days'));if(!Number.isInteger(value)||value<1||value>365)return;const c=clone(content);c.days=value;c.lastUpdated=Date.now();persist(c);});
document.querySelector('#clock-form')?.addEventListener('submit',e=>{e.preventDefault();const value=new Date(new FormData(e.target).get('clock')).getTime();if(!Number.isFinite(value))return;try{localStorage.setItem('site-base-demo-clock',String(value));render();toast('表示確認時刻を変更しました。');}catch{toast('確認時刻を保存できませんでした。');}});
document.querySelector('#clock-reset')?.addEventListener('click',()=>{localStorage.removeItem('site-base-demo-clock');render();toast('現在時刻に戻しました。');});
document.querySelector('#reset')?.addEventListener('click',()=>review('見本のリセットを確認',[['対象',PROFILES[selected]],['変更後','初期状態を作業内容へ追加します。最後の確定まで公開側は変わりません。']],()=>{const c=seed(selected);c.inquiries=read(selected).inquiries;return persist(c,'初期状態を作業内容へ追加しました。');},null,null,{confirmLabel:'初期内容を作業一覧へ追加',notice:'初期内容を作業一覧へ追加します。最後の確定まで公開側は変わりません。'}));
}
window.addEventListener('storage',e=>{if(e.key==='site-base-demo-clock'||e.key===WORK_KEY||e.key==='site-base-display-sample-v1'){published=read(selected);if(page==='admin'){if(e.key===WORK_KEY)work=readWork(selected);content={...clone(work?.draft||published),inquiries:published.inquiries};}else content=published;if(dialog.open){toast('別の画面で更新されました。入力内容を控え、編集を開き直してください。');return;}render();}});
window.addEventListener('pageshow',()=>{if(CONNECTED)return;published=read(selected);content=page==='admin'?{...clone(work?.draft||published),inquiries:published.inquiries}:published;if(!dialog.open)render();});
let lastClock=now();setInterval(()=>{const current=now();const changed=[...content.items,...content.news].some(i=>stateOf(i,lastClock)!==stateOf(i,current)||hasNew(i,lastClock,content.days)!==hasNew(i,current,content.days));lastClock=current;if(changed&&!dialog.open&&(page==='site'||tab==='items'||tab==='news'))render();},30000);
async function refreshConnection(initial=false){if(!CONNECTED)return;const latest=await loadShared(selected,page==='admin'||page==='site'&&new URLSearchParams(location.search).get('preview')==='1');published=latest;if(initial||!dialog.open&&!document.querySelector('#item-detail')?.open&&!pendingForms().length){content=page==='admin'?{...clone(work?.draft||latest),inquiries:clone(latest.inquiries)}:latest;render();}}
async function start(){if(CONNECTED){app.innerHTML='<main class="entry"><p>共有内容を読み込んでいます…</p></main>';try{await refreshConnection(true);}catch(error){app.innerHTML=`<main class="entry"><p role="alert">${esc(error.message)}</p><button id="load-again">再読み込み</button></main>`;document.querySelector('#load-again').onclick=()=>location.reload();}}else render();}
start();
if(CONNECTED){window.addEventListener('focus',()=>refreshConnection().catch(error=>toast(error.message)));setInterval(()=>{if(page==='site'&&document.visibilityState==='visible')refreshConnection().catch(()=>{});},30000);}
document.fonts.ready.then(fitAdminByline);
window.addEventListener('resize',fitAdminByline);

// Protect in-app exits; opening another tab does not end this editing session.
app.addEventListener('click',e=>{const a=e.target.closest('a[href]');if(page!=='admin'||!a||a.target==='_blank'||e.ctrlKey||e.metaKey||e.shiftKey||a.getAttribute('href').startsWith('#'))return;if(hasPending()){e.preventDefault();e.stopImmediatePropagation();requestNavigation(()=>location.assign(a.href));}},true);
app.addEventListener('change',e=>{if(page==='admin'&&e.target.id==='profile'&&hasPending()){const chosen=e.target.value;e.preventDefault();e.stopImmediatePropagation();e.target.value=selected;requestNavigation(()=>location.assign(`./admin.html?profile=${encodeURIComponent(chosen)}`));}},true);
